struct SupplyAuthority final:PoliticalSupplyPolicyAuthorityRead {
 SupplyLedgerFixture& f;bool historical=true,current=true;explicit SupplyAuthority(SupplyLedgerFixture& value):f(value){}
 Outcome<PoliticalSupplyPolicyAuthoritySource> source(const ActingAuthority& a,const PoliticalSupplyPolicyMandate& m,Integer tick)const{PoliticalSupplyPolicyAuthoritySource s;s.source_identity=f.common.state().identity;s.mandate=m;s.authority=a;s.grant_id="grant";s.issued_tick=tick;s.registration.source_identity=s.source_identity;s.registration.registration_fact_id=f.registered;s.registration.site_id="town";s.registration.successor_organization_id="new";s.registration.public_inventory_ids={"grain.store"};return {true,s,{}};}
 Outcome<PoliticalSupplyPolicyAuthoritySource> political_supply_policy_authority(const ActingAuthority& a,const PoliticalSupplyPolicyMandate& m)const override{if(!current)return {false,{},common_failure("TestGrantRevoked").error};return source(a,m,f.common.tick());}
 Outcome<PoliticalSupplyPolicyAuthoritySource> political_supply_policy_authority_before_issue(const ActingAuthority& a,const PoliticalSupplyPolicyMandate& m,const StableId&,const StableId&,Integer tick)const override{if(!historical)return {false,{},common_failure("TestHistoryAfterWriteDenied").error};return source(a,m,tick);}
};
struct SupplyAdoptions final:PoliticalSupplyAdoptionRead {
 SupplyLedgerFixture& f;StableId policy,approval;bool allowed=true,history=true;mutable bool saw_new_observation=false;explicit SupplyAdoptions(SupplyLedgerFixture& value):f(value){}
 Outcome<std::optional<PoliticalSupplyAdoptionSource>> value(const StableId& id,Integer tick,bool permission)const{auto pure=validate_economic_supply_policy_ledger(f.context());if(!pure.ok)return {false,{},pure.error};if(id!=policy||approval.empty())return {true,{}, {}};return {true,PoliticalSupplyAdoptionSource{f.common.state().identity,id,f.registered,"grain.source",approval,approval,"new","town",0,tick,permission,permission?StableId{}:StableId{"TestPolicySuspended"}}, {}};}
 Outcome<std::optional<PoliticalSupplyAdoptionSource>> political_supply_adoption(const StableId& id)const override{return value(id,f.common.tick(),allowed);}
 Outcome<std::optional<PoliticalSupplyAdoptionSource>> political_supply_adoption_before_observation(const StableId& id,const StableId& fact,Integer tick)const override{if(!history&&tick==2)saw_new_observation=f.state.observations.find(fact)!=nullptr&&f.common.state().facts.find(fact)!=nullptr;return value(id,tick,history||tick==1);}
};
