 auto issued=issue_economic_supply_policy(f.common,f.state,x,"officer",command);check(issued.ok&&f.state.policies.size()==1&&f.common.wallet("cash")->balance==initial_balance&&f.common.wallet("cash")->reserved.empty());EconomicSupplyPolicyAccess read(x);auto source=read.economic_supply_policy(issued.value.policy_fact_id);check(source.ok&&source.value&&!source.value->new_contracts_allowed&&source.value->unavailable_code=="EconomicSupplyPolicyPending");auto observe=refresh_economic_supply_observations(f.common,f.state,x);check(observe.ok&&observe.value.empty()&&f.state.observations.empty());
