 auto historical=read.economic_supply_observation(observed_id);check(historical.ok&&historical.value&&historical.value->observation.observation.physical_amount==0);adoptions.allowed=false;source=read.economic_supply_policy(adoptions.policy);check(source.ok&&source.value&&!source.value->new_contracts_allowed&&source.value->last_observation_fact_id==observed_id&&validate_economic_supply_policies(x).ok);observe=refresh_economic_supply_observations(f.common,f.state,x);check(observe.ok&&observe.value.empty()&&f.common.state().next_instance_id==ids);
 adoptions.allowed=true;f.common.state().identity.tick=2;const auto prior=encode_economic_supply_policy_state(f.state);adoptions.history=false;observe=refresh_economic_supply_observations(f.common,f.state,x);check(!observe.ok&&adoptions.saw_new_observation&&f.common.state().next_instance_id==ids&&compare_boundary(prior,encode_economic_supply_policy_state(f.state)).exact());adoptions.history=true;
 auto sp=f.common.begin_savepoint();check(sp.ok);auto candidate_quote=preview_economic_supply_policy(x,"officer",command);check(candidate_quote.ok);const auto saved=f.state;auto second=issue_economic_supply_policy_in_candidate(f.common,f.state,x,"officer",command,candidate_quote.value);check(second.ok&&f.state.policies.size()==3);check(f.common.rollback_savepoint(sp.value).ok);f.state=saved;check(validate_economic_supply_policies(x).ok&&f.common.state().next_instance_id==ids);
